                if (volumeOsc[0] < 0)
                {
                    // Ease of Movement crosses below zero (price moving downward with light volume)
                    if (easeOfMovement[0] < 0 && easeOfMovement[1] >= 0)
                    {
                        // TSF shows downward trend
